// dispatcherOf resolves a kind token, already trimmed and lower cased,
// through the canonical kinds and the alias space.
func dispatcherOf(token string) dispatcher {
	switch token {
	case "cegjegyzekszam", "hu_cegjegyzekszam":
		return dispatcherCegjegyzekszam
	case "cnpj", "br_cnpj":
		return dispatcherCnpj
	case "codice_fiscale_impresa", "it_codice_fiscale_impresa":
		return dispatcherCodiceFiscaleImpresa
	case "company_number", "company_registration_number", "crn", "gb_company_number", "uk_company_number":
		return dispatcherCompanyNumber
	case "corporate_number", "hojin_bango", "houjin_bangou", "jp_corporate_number":
		return dispatcherCorporateNumber
	case "cro_number", "ie_cro_number":
		return dispatcherCroNumber
	case "cui", "cif", "ro_cui":
		return dispatcherCui
	case "cvr", "cvr_nummer", "dk_cvr":
		return dispatcherCvr
	case "duns", "dnb", "duns_number":
		return dispatcherDuns
	case "eik", "bg_eik", "bulstat":
		return dispatcherEik
	case "ein", "federal_tax_id", "us_ein":
		return dispatcherEin
	case "enterprise_number", "be_enterprise_number", "numero_entreprise", "ondernemingsnummer":
		return dispatcherEnterpriseNumber
	case "eori", "eori_number":
		return dispatcherEori
	case "euid":
		return dispatcherEuid
	case "firmenbuchnummer", "at_firmenbuchnummer", "fn":
		return dispatcherFirmenbuchnummer
	case "gemi", "el_gemi", "gr_gemi":
		return dispatcherGemi
	case "handelsregisternummer", "de_handelsregisternummer", "hrb":
		return dispatcherHandelsregisternummer
	case "he_number", "cy_he_number":
		return dispatcherHeNumber
	case "ico", "cz_ico", "sk_ico":
		return dispatcherIco
	case "juridinio_asmens_kodas", "lt_juridinio_asmens_kodas":
		return dispatcherJuridinioAsmensKodas
	case "krs", "pl_krs":
		return dispatcherKrs
	case "kvk", "kvk_nummer", "nl_kvk":
		return dispatcherKvk
	case "lei":
		return dispatcherLei
	case "maticna_stevilka", "si_maticna_stevilka":
		return dispatcherMaticnaStevilka
	case "mbr_number", "mt_mbr_number":
		return dispatcherMbrNumber
	case "mbs", "hr_mbs":
		return dispatcherMbs
	case "nif", "es_nif":
		return dispatcherNif
	case "nipc", "pt_nipc":
		return dispatcherNipc
	case "organisationsnummer", "se_organisationsnummer":
		return dispatcherOrganisationsnummer
	case "rcs_number", "lu_rcs_number":
		return dispatcherRcsNumber
	case "registracijas_numurs", "lv_registracijas_numurs":
		return dispatcherRegistracijasNumurs
	case "registrikood", "ee_registrikood":
		return dispatcherRegistrikood
	case "siren", "fr_siren":
		return dispatcherSiren
	case "siret", "fr_siret":
		return dispatcherSiret
	case "uscc", "cn_uscc", "unified_social_credit_code", "usci":
		return dispatcherUscc
	case "vat", "vat_id", "vat_number":
		return dispatcherVat
	case "y_tunnus", "business_id", "fi_y_tunnus":
		return dispatcherYTunnus
	}
	return noDispatcher
}

