// countryAlias maps a normalized country token onto a canonical code. A
// token the dispatcher does not alias is returned unchanged.
func countryAlias(d dispatcher, code string) string {
	switch d {
	case dispatcherVat:
		switch code {
		case "EL":
			return "GR"
		case "UK":
			return "GB"
		}
	}
	return code
}

