// globalTarget is the single GLOBAL definition of a dispatcher, when it
// declares one. A dispatcher with a GLOBAL target has no other.
func globalTarget(d dispatcher) (definition, bool) {
	switch d {
	case dispatcherDuns:
		return defDuns, true
	case dispatcherEori:
		return defEori, true
	case dispatcherLei:
		return defLei, true
	}
	return 0, false
}

