// preCanonicalize9 is the routing pre-canonicalizer of cegjegyzekszam, cnpj, codice_fiscale_impresa, company_number, corporate_number, cro_number, cui, cvr, duns, eik, ein, enterprise_number, eori, firmenbuchnummer, gemi, handelsregisternummer, he_number, ico, juridinio_asmens_kodas, krs, kvk, lei, maticna_stevilka, mbr_number, mbs, nif, nipc, organisationsnummer, rcs_number, registracijas_numurs, registrikood, siren, siret, uscc, vat, y_tunnus.
//
// It performs only the normalization routing needs, and can neither add,
// replace nor interpret a prefix.
func preCanonicalize9(w *rt.Buf) {
	w.TrimWhitespace()
	w.RemoveWhitespace()
	w.UppercaseASCII()
	w.RemoveChars("-./_")
}

// preCanonicalize10 is the routing pre-canonicalizer of euid.
//
// It performs only the normalization routing needs, and can neither add,
// replace nor interpret a prefix.
func preCanonicalize10(w *rt.Buf) {
	w.TrimWhitespace()
	w.RemoveWhitespace()
	w.UppercaseASCII()
}

// preCanonicalize runs the pre-canonicalizer of a dispatcher exactly once
// on the raw value.
