// formatFirmenbuchnummerAT implements the format rule of firmenbuchnummer AT.
func formatFirmenbuchnummerAT(c ruleCtx, subject rt.View) stepResult {
	if subject.IsEmpty() {
		return invalidStep(ReasonEmpty, "at.firmenbuchnummer.empty")
	}
	if !subject.LengthBetween(2, 7) {
		return invalidStep(ReasonInvalidLength, "at.firmenbuchnummer.length")
	}
	if !subject.ASCIIAlphanumeric() {
		return invalidStep(ReasonInvalidCharacters, "at.firmenbuchnummer.characters")
	}
	if !((subject.LengthEq(2) && subject.Slice(0, 1).ASCIIDigits() && subject.CharAtIn(1, "ABCDEFGHIJKLMNOPQRSTUVWXYZ")) || (subject.LengthEq(3) && subject.Slice(0, 2).ASCIIDigits() && subject.CharAtIn(2, "ABCDEFGHIJKLMNOPQRSTUVWXYZ")) || (subject.LengthEq(4) && subject.Slice(0, 3).ASCIIDigits() && subject.CharAtIn(3, "ABCDEFGHIJKLMNOPQRSTUVWXYZ")) || (subject.LengthEq(5) && subject.Slice(0, 4).ASCIIDigits() && subject.CharAtIn(4, "ABCDEFGHIJKLMNOPQRSTUVWXYZ")) || (subject.LengthEq(6) && subject.Slice(0, 5).ASCIIDigits() && subject.CharAtIn(5, "ABCDEFGHIJKLMNOPQRSTUVWXYZ")) || (subject.LengthEq(7) && subject.Slice(0, 6).ASCIIDigits() && subject.CharAtIn(6, "ABCDEFGHIJKLMNOPQRSTUVWXYZ"))) {
		return invalidStep(ReasonInvalidFormat, "at.firmenbuchnummer.shape")
	}
	return validStep()
}

// formatEnterpriseNumberBE implements the format rule of enterprise_number BE.
func formatEnterpriseNumberBE(c ruleCtx, subject rt.View) stepResult {
	if subject.IsEmpty() {
		return invalidStep(ReasonEmpty, "be.enterprise_number.empty")
	}
	if !subject.LengthEq(10) {
		return invalidStep(ReasonInvalidLength, "be.enterprise_number.length")
	}
	if !subject.ASCIIDigits() {
		return invalidStep(ReasonInvalidCharacters, "be.enterprise_number.characters")
	}
	if !(subject.HasPrefix("0") || subject.HasPrefix("1")) {
		return invalidStep(ReasonInvalidFormat, "be.enterprise_number.leading")
	}
	return validStep()
}

// formatEikBG implements the format rule of eik BG.
func formatEikBG(c ruleCtx, subject rt.View) stepResult {
	if subject.IsEmpty() {
		return invalidStep(ReasonEmpty, "bg.eik.empty")
	}
	if !(subject.LengthEq(9) || subject.LengthEq(13)) {
		return invalidStep(ReasonInvalidLength, "bg.eik.length")
	}
	if !subject.ASCIIDigits() {
		return invalidStep(ReasonInvalidCharacters, "bg.eik.characters")
	}
	return validStep()
}

// formatCnpjBR implements the format rule of cnpj BR.
func formatCnpjBR(c ruleCtx, subject rt.View) stepResult {
	if subject.IsEmpty() {
		return invalidStep(ReasonEmpty, "cnpj.empty")
	}
	if !subject.LengthEq(14) {
		return invalidStep(ReasonInvalidLength, "cnpj.length")
	}
	if !subject.ASCIIAlphanumeric() {
		return invalidStep(ReasonInvalidCharacters, "cnpj.characters")
	}
	if !subject.Slice(12, 14).ASCIIDigits() {
		return invalidStep(ReasonInvalidCharacters, "cnpj.check_digits")
	}
	return validStep()
}

// formatUsccCN implements the format rule of uscc CN.
func formatUsccCN(c ruleCtx, subject rt.View) stepResult {
	if subject.IsEmpty() {
		return invalidStep(ReasonEmpty, "uscc.empty")
	}
	if !subject.LengthEq(18) {
		return invalidStep(ReasonInvalidLength, "uscc.length")
	}
	if !subject.ASCIICharset("0123456789ABCDEFGHJKLMNPQRTUWXY") {
		return invalidStep(ReasonInvalidCharacters, "uscc.characters")
	}
	return validStep()
}

