// formatVatFR implements the format rule of vat FR.
func formatVatFR(c ruleCtx, subject rt.View) stepResult {
	n8 := subject.Slice(2, 4)
	n15 := subject.SliceFrom(4)
	if subject.IsEmpty() {
		return invalidStep(ReasonEmpty, "vat.fr.empty")
	}
	if !subject.LengthEq(13) {
		return invalidStep(ReasonInvalidLength, "vat.fr.length")
	}
	if !subject.HasPrefix("FR") {
		return invalidStep(ReasonInvalidFormat, "vat.fr.prefix")
	}
	if !(n8.ASCIIDigits() || (c.profile == Compatible && n8.ASCIIAlphanumeric())) {
		return invalidStep(ReasonInvalidCharacters, "vat.fr.key_characters")
	}
	if !n15.ASCIIDigits() {
		return invalidStep(ReasonInvalidCharacters, "vat.fr.siren_characters")
	}
	// The callee reason code and message key propagate unchanged.
	if r := formatSirenFR(c, n15); r.status != Valid {
		return r
	}
	return validStep()
}

